//459eb0 and all reachable initializers execute natively, including RNG.
//458590 is an explicit boolean leaf;59460 executes as its realphase1 no-op.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZNov04IdlePoseOracle extends GhidraScript{
 static final long U=0x5e30c8L,R=0x60ec00L,S=0x7fff0000L,RET=0x12345000L;
 long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}void back(EmulatorHelper e)throws Exception{long sp=e.readRegister("ESP").longValue(),ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<4096;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.writeMemory(toAddr(U),new byte[192]);e.writeMemory(toAddr(R),new byte[72]);e.writeMemory(toAddr(0x58aaaa),new byte[16384]);put(e,U+44,2,500);put(e,U+46,2,600);int cell=((600+11)*8&0xff80)+((500+5)>>4);put(e,0x58aaaa+cell,1,new int[]{0,9,38,39,42,128,16,35}[s/31%8]);put(e,U+0x35,1,s%37==0?2:1);put(e,U+0x7c,1,new int[]{0,3,15,16,17,18,1,2,4}[s/17%9]);put(e,U+0x8a,1,s%19==0?32:0);put(e,U+0x5e,1,new int[]{-1,0,1,7}[s/11%4]);put(e,U+0x5f,1,s%23==0?255:0);put(e,U+0x7d,1,s%13==0?2:1);put(e,U+0x7e,2,0x9321);put(e,U+0x80,1,55);put(e,U+0x32,2,-12);put(e,U+0x82,2,1234);put(e,U+0x39,1,s%8);put(e,U+0x88,2,0x7134);put(e,R+65,1,s%6);put(e,0x622dc4,1,s%41==0?1:0);put(e,0x622d40,2,s%43==0?2:0);for(int i=0;i<5;i++)put(e,0x622cdc+i*4,4,(s*(i+1)+i+1)&0xffffffffL);
 e.setBreakpoint(toAddr(RET));e.setBreakpoint(toAddr(0x458590));e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",U);if(!e.run(toAddr(0x459eb0),null,monitor))throw new Exception(e.getLastError());int queries=0;while(e.readRegister("EIP").longValue()!=RET){if(++queries>1)throw new Exception("query loop");e.writeRegister("EAX",s%5==0?1:0);back(e);}
 out.print("{\"scenario\":"+s+",\"queries\":"+queries);for(int[]f:new int[][]{{0x35,1},{0x32,2},{0x39,1},{0x7d,1},{0x7e,2},{0x80,1},{0x82,2},{0x88,2}}){long v=read(e,U+f[0],f[1]);if(f[0]==0x32||f[0]==0x82)v=(short)v;out.print(",\"u"+f[0]+"\":"+v);}for(int i=0;i<5;i++)out.print(",\"rng"+i+"\":"+read(e,0x622cdc+i*4,4));out.println("}");}finally{e.dispose();}}}}
}
